"$files = Get-ChildItem -File | Where-Object { $_.Name -notmatch '\.ps1$' -and $_.Name -notmatch 'done\.txt' }
if (-not (Test-Path Compressed)) { New-Item -ItemType Directory -Path Compressed | Out-Null }

$pool = [runspacefactory]::CreateRunspacePool(1, 10)
$pool.Open()
$jobs = @()

foreach ($file in $files) {
    $job = [powershell]::Create().AddScript({
        param($f)
        $out = "Compressed\$($f.Name)"
        if ($f.Extension -match '\.mp4$|\.mov$|\.avi$') {
            # Video compression
            $cmd = "ffmpeg -y -v quiet -i `"$($f.FullName)`" -c:v libx264 -crf 28 -preset veryfast -c:a aac -b:a 128k `"$out`""
            Invoke-Expression $cmd
        } else {
            # Image compression
            $cmd = "ffmpeg -y -v quiet -i `"$($f.FullName)`" -q:v 5 `"$out`""
            Invoke-Expression $cmd
        }
        return $f.Name
    }).AddArgument($file)

    $job.RunspacePool = $pool
    $jobs += [PSCustomObject]@{
        Pipe = $job
        Status = $job.BeginInvoke()
    }
}

while ($jobs.Status.IsCompleted -contains $false) {
    Start-Sleep -Milliseconds 500
}

$pool.Close()
$pool.Dispose()

$origSize = ($files | Measure-Object -Property Length -Sum).Sum
$newFiles = Get-ChildItem -Path Compressed -File
$newSize = ($newFiles | Measure-Object -Property Length -Sum).Sum

[PSCustomObject]@{
    OriginalSizeMB = [math]::Round($origSize / 1MB, 2)
    NewSizeMB = [math]::Round($newSize / 1MB, 2)
    FilesProcessed = $newFiles.Count
} | ConvertTo-Json

